import { MakeLogicType, actions, kea, path, reducers } from 'kea'

export const METRICS_DATE_RANGES = [
    { value: 1, label: 'Last hour' },
    { value: 24, label: 'Last 24 hours' },
    { value: 24 * 7, label: 'Last 7 days' },
    { value: 24 * 30, label: 'Last 30 days' },
] as const

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalMetricsPeriodLogicValues {
    hours: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalMetricsPeriodLogicActions {
    setHours: (hours: number) => {
        hours: number
    }
}

export type transactionalMetricsPeriodLogicType = MakeLogicType<
    transactionalMetricsPeriodLogicValues,
    transactionalMetricsPeriodLogicActions
>

/** The period the Metrics tab shows, shared by both channels so switching keeps it. */
export const transactionalMetricsPeriodLogic = kea<transactionalMetricsPeriodLogicType>([
    path(['products', 'workflows', 'frontend', 'Transactional', 'metrics', 'transactionalMetricsPeriodLogic']),
    actions({
        setHours: (hours: number) => ({ hours }),
    }),
    reducers({
        hours: [(24 * 7) as number, { setHours: (_, { hours }) => hours }],
    }),
])
